class Solution {
public:
    string makeFancyString(string s) {
        string res = "";
        for (char c : s) {
            int n = res.size();
            if (n >= 2 && res[n - 1] == c && res[n - 2] == c) continue;
            res += c;
        }
        return res;
    }
};

class Solution {
    public String makeFancyString(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            int len = sb.length();
            if (len >= 2 && sb.charAt(len - 1) == c && sb.charAt(len - 2) == c) continue;
            sb.append(c);
        }
        return sb.toString();
    }
}

var makeFancyString = function(s) {
  const res = [];
  for (const c of s) {
    const len = res.length;
    if (len >= 2 && res[len - 1] === c && res[len - 2] === c) continue;
    res.push(c);
  }
  return res.join('');
};
